programs.haiku:
"""Two word families of opposite sign, plus context rules for 'of' and 'by'.

Positive: words describing the look and extent of terrain or scenery (vast, tall,
cliffs, lush, mist, hills, miles; and Chinese 蜿蜒, 起伏, 山势, 秀, 雄, 绿化).
Negative: universal/temporal quantifiers and concessive words (every, never, yet,
whether, often, entire, though) and a few technical verbs (ignore, check, support, code).
Context: 'by' after a spatial passive (surrounded/separated/bordered by) is positive,
'by' after a making/measuring verb (produced/obtained/calculated by) is negative.
'of' after a shape or group noun (series, form, network, plurality) is positive,
'of' after 'range', 'plenty', 'side', 'mixture' is negative.
"""

READS = ()

SCENERY = {
    "vast": 0.28, "tall": 0.14, "lush": 0.25, "mist": 0.10, "hills": 0.2, "hill": 0.09,
    "cliffs": 0.45, "trees": 0.08, "miles": 0.15, "formed": 0.12, "formation": 0.11,
    "surrounded": 0.3, "separated": 0.16,
    "蜿": 1.0, "蜒": 0.9, "起伏": 1.0, "势": 0.5, "秀": 0.8, "雄": 0.4,
    "绿化": 0.33, "峰": 0.12, "谷": 0.1, "丛": 0.6, "旎": 0.6, "茂": 0.35,
    "绵": 0.35, "覆盖率": 0.5,
}
QUANTIFIERS = {
    "every": -0.09, "never": -0.10, "yet": -0.13, "whether": -0.10, "often": -0.08,
    "entire": -0.15, "major": -0.09, "though": -0.07, "although": -0.04,
    "ignore": -0.15, "check": -0.065, "support": -0.09, "code": -0.08, "growth": -0.11,
}
SPATIAL_PASSIVE = {"surrounded", "separated", "bordered", "delimited", "fed", "bounded"}
MAKING_PASSIVE = {"produced", "obtained", "calculated", "determined", "developed",
                  "designed", "generated", "made", "caused"}
SHAPE_NOUNS = {"series", "form", "formation", "plurality", "network", "amounts",
               "examples", "thousands", "number", "variety"}
SPREAD_NOUNS = {"range", "plenty", "side", "mixture", "way", "heart", "snippet"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    value = SCENERY.get(tok, QUANTIFIERS.get(tok, 0.0))
    if tok == "by":
        if prev in SPATIAL_PASSIVE:
            value = 0.5
        elif prev in MAKING_PASSIVE:
            value = -0.1
    elif tok == "of":
        if prev in SHAPE_NOUNS:
            value = 0.12
        elif prev in SPREAD_NOUNS:
            value = -0.15
    return carry, float(value)

programs.sol:
"""A lexical approximation of the component's strongest readable responses.

Rule/stipulation and official-record words respond negatively. An explicit
set of Chinese characters responds positively; this is not a general rule
for names. Smaller responses model selected restrictive/descriptive words,
data-handling identifiers, indentation and conversation boundaries.
State joins split words, retains the preceding signal on 'of', and tracks
recent Japanese kana. State resets at document boundaries. Most other
word-specific responses are left unmodeled.
"""
import re

READS = ()

# Literal characters: auspicious/Thai, spring, pottery, marsh, field, penetrate.
CHARACTERS = {'泰': 1.85, '泉': 0.68, '陶': 0.65, '泽': 0.45,
              '澤': 0.45, '田': 0.28, '透': 0.49, '莱': 0.2, '萊': 0.2}
PRESCRIPTION = {
    'statutory': -0.67, 'statute': -0.18, 'statutes': -0.1,
    'stip': -0.62, 'prescribed': -0.5, 'prescribe': -0.31,
    'provisions': -0.41, 'provision': -0.28,
    'specified': -0.28, 'specifies': -0.18,
    'specify': -0.14, 'specifying': -0.14,
    'official': -0.2, 'officially': -0.23,
    'duly': -0.33, 'contractual': -0.23,
    'record': -0.12, 'records': -0.19, 'recorded': -0.17,
}
RESTRICTIVE = {'always', 'even', 'exactly', 'rather', 'solely'}
UNQUALIFIED = {'whatever', 'whichever', 'whatsoever', 'merely'}
PRESERVATION = {'maintain', 'maintains', 'maintaining', 'remain',
                'remains', 'remained', 'fixed', 'complete'}
KNOWLEDGE = {'know', 'knew', 'question'}
DESCRIPTION = {'particular', 'details', 'described', 'following'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    if not same_document:
        previous, position, japanese, tail, previous_value = '', 0, 0, '', 0.0
    else:
        _, previous, position, japanese, tail, previous_value = carry
        position += 1
        japanese = max(0, japanese - 1)
    raw = prefix.token_strings[-1]
    text = raw.strip()
    joined = tail + raw if raw[:1].isascii() and raw[:1].isalpha() else raw
    match = re.search(r'[a-zA-Z]+$', joined)
    tail = match.group().casefold()[-48:] if match else ''
    if any('\u3040' <= c <= '\u30ff' for c in text):
        japanese = 24
    # A final byte fragment can complete a character that decoded alone as �.
    if '\ufffd' in text and same_document:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in CHARACTERS:
            text = completed
    word = text.casefold()
    value = -0.001
    if text in CHARACTERS:
        value = CHARACTERS[text]
    elif '规定' in text or '規定' in text:
        if text in {'规定', '規定'}:
            value = -1.45 if japanese else -1.95
        else:
            value = -1.5
    elif text in {'法定', '约定', '約定', '依法'}:
        value = {'法定': -1.0, '约定': -0.8,
                 '約定': -0.8, '依法': -0.55}[text]
    elif word in PRESCRIPTION:
        value = PRESCRIPTION[word]
    elif word.startswith('alleg') or word in {'declare', 'declared', 'declares'}:
        value = -0.18
    elif tail.startswith('stipul') and word.startswith('ulat'):
        value = -0.22 if word in {'ulation', 'ulations'} else -0.69
    elif previous in {'official', 'stat'} and word in {'ly', 'utory'}:
        value = -0.45
    elif word in RESTRICTIVE:
        value = -0.075
    elif word in UNQUALIFIED:
        value = -0.15
    elif word in {'only', 'without'}:
        value = -0.04
    elif word in PRESERVATION:
        value = -0.115
    elif word in KNOWLEDGE:
        value = 0.075
    elif word in DESCRIPTION:
        value = 0.07
    elif word in {'pattern', 'patterns', 'consistent', 'consistency', 'consistently'}:
        value = 0.12
    elif word == 'ervative' and tail == 'conservative':
        value = 0.36
    elif word == 'bed' and tail == 'testbed':
        value = 0.077
    elif word in {'valley', 'valleys'}:
        value = 0.32
    elif word in {'datetime', 'serde'}:
        value = 0.4 if word == 'datetime' or raw[:1].isspace() else 0.25
    elif word in {'val', 'validator'}:
        value = (0.17 if raw[:1].isspace() else 0.115) if word == 'val' else 0.27
    elif text in {'.Sprintf', '.Errorf'}:
        value = -0.4 if text == '.Sprintf' else -0.17
    elif word in {'split', '.split'}:
        value = -0.14
    elif text == '.go':
        value = -0.054
    elif text == '<|im_end|>':
        value = -0.044
    elif text == '</tool_response>':
        value = -0.071
    elif text in {'<think>', '</think>'}:
        value = 0.055
    elif text in {'<tool_call>', '</tool_call>'}:
        value = 0.035
    elif raw and all(c == '\t' for c in raw):
        value = -0.015 - 0.012 * len(raw)
    elif text == '良心':
        value = 0.45
    if position == 0 and word in {'title', '##'}:
        value = -0.41 if word == 'title' else -0.306
    # Closed-class continuations often retain the preceding lexical signal.
    if word == 'of':
        value = -0.006 + 0.84 * previous_value
    return (doc, word, position, japanese, tail, value), float(value)

"""Approximate a delimiter-versus-familiarity lexical response.

Display-math dollar pairs are strongly negative, but nearby repetition weakens
that response. Single dollars and inline code backticks are weaker negatives;
indentation and variable syntax soften the dollar rule. Orientation,
familiarity, confusion, convenience, convention, and concentration words are
positive. LaTeX brackets and diff hunk markers are weakly negative.
Unrecognized tokens give zero. The fading count and text tail reset per document.
"""
import math

READS = ()


def lexical(text):
    word = text.strip().lower().strip('.-_')
    if word == 'orientation':
        return 1.65
    if word in ('orient', 'oriented', 'orientations'):
        return 1.0
    if word.startswith(('familiar', 'unfamiliar', 'confus')):
        return 1.25
    if word.startswith(('conveni', 'inconveni')):
        return 1.35
    if word == 'friendly':
        return 1.25 if text.startswith('-') else 0.3
    if word in ('convention', 'conventions'):
        return 0.9
    if word.startswith('concentrat'):
        return 0.8 if word == 'concentration' else 0.55
    # Familiarity, habit, smoothness, and convenience translation equivalents.
    if word in ('顺', '順', '习惯', '習慣'):
        return 2.2
    if word in ('熟', '熟悉', '方便') or word.startswith('удоб'):
        return 1.35
    return 0.0


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    _, count, tail, previous = (doc, 0., '', '') if first else carry
    count *= 0.98
    token = text.strip()
    value = lexical(text)
    if '$$' in text:
        base, gain = (-4.8, 1.1) if text.startswith(' ') else (-3.1, 0.6)
        value = min(-1., base + gain * math.log1p(count))
        if first:
            value = -5.72 if text.startswith(' ') else -4.74
    elif token in ('$', '${', '$('):
        value = -0.65 if token == '$' else -0.75
        if first and token == '$':
            value = -1.3
        elif text == ' $':
            variable = previous[-1:].isspace() or '->' in tail or '$this' in tail
            value = 0.05 if variable else -0.5
            if not variable and ('\\' in tail or count > 0.1):
                value = -0.75
        elif '\n' in text:
            value = -0.35
    elif '$' in text:
        if '\\$' in text or token == '$\\':
            value = -0.5
        elif token.startswith(('($', '[$')):
            value = 0.05
        elif token in ('$,', '$.'):
            value = -0.27 if token == '$,' else -0.14
        elif token.endswith('$') or (token.startswith('$') and len(token) == 2):
            value = -0.45
    elif '`' in text:
        value = -0.34 if token in ('`', ')`', '}`') else -0.17
        if first or previous[-1:].isspace():
            value = -0.12
        if '\n' in text or token == '``':
            value = 0.0
        elif '```' in text:
            value = -0.15
    elif token == '@@':
        value = -0.3 if text.startswith(' ') else -0.8
    elif token in ('\\(', '\\['):
        value = -0.35 if token == '\\(' else -0.25
    elif text == '\\' and '$$' in previous:
        value = -0.8
    if '$$' in text:
        count += 1.0
    return (doc, count, (tail + text)[-150:], text), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:1668 -- a word-family detector with signed output.

What it does: this component is a lexical feature, not a context feature. Its
activation is set by which word the current token belongs to, and the sign depends on
the family:

  * "vent" (vent, vents, venting, vented, ventilation) is pushed negative, the
    strongest single case (about -0.3 to -1.0 on " vent" in the harvest windows);
  * fire / danger / damage words (fire, flame, ignition, explosion, damage, danger,
    accident, toxic, burn, smoke, hazard) are pushed mildly negative;
  * machinery words (engine, shaft, crankshaft, piston, pump, pipe, motor, gear,
    cylinder) are pushed positive;
  * coating / disposal words (coat, coated, coating, dispose, disposed, deflect,
    supplied, excessive) are pushed negative.

Every other token predicts 0. The values are the family means measured on training
text (rounded). Word matching is case-insensitive and ignores the leading space that
BPE tokens carry.

What it does not capture: most of the component's variance is a diffuse spread of
small values over ordinary function words (" of", " to", " the", ...) whose sign depends
on context, which a word list cannot predict. On held-out training text this program
explains almost none of the variance. A per-token table of means would explain more,
but it would be a list of arbitrary token ids, so it is not used here.
"""

READS = ()

FAMILY_VALUE = {
    "vent": -0.09,
    "fire": -0.05,
    "machine": 0.10,
    "coat": -0.22,
}

FAMILY = {
    "vent": {"vent", "vents", "venting", "vented", "ventilation"},
    "fire": {
        "fire", "fires", "flame", "flames", "ignition", "explosion", "explosions",
        "explode", "explosive", "damage", "damaged", "damages", "danger", "dangerous",
        "accident", "accidents", "toxic", "burn", "burning", "smoke", "hazard",
        "hazards", "detrimental",
    },
    "machine": {
        "engine", "engines", "shaft", "crankshaft", "piston", "pistons", "pump",
        "pumps", "pipe", "pipes", "pipeline", "motor", "gear", "gears", "cylinder",
    },
    "coat": {
        "coat", "coated", "coating", "coatings", "deflect", "disposed", "dispose",
        "disposing", "supplied", "excessive",
    },
}

WORD_VALUE = {w: FAMILY_VALUE[f] for f, words in FAMILY.items() for w in words}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return carry, float(WORD_VALUE.get(word, 0.0))

programs.sol:
"""A graded lexical signal for quantitative modeling and scientific inference.

Calculation/simulation nouns are strongest. Numerical analysis, models and
computation follow; evidence and solution/procedure words are weaker. This does
not calculate anything. It joins split English words, weakens identifier and
capitalized forms, and uses the preceding word to recognize scientific prose.
Uppercase tool labels and exit/status codes are not scientific observations or
source code. Everything else gets zero; document changes reset the word state.
"""
READS = ()


def response(w):
    if w.startswith(('calculat', 'simulat')):
        if w.endswith(('ion', 'ions')):
            return 2.2 + 0.55 * w.endswith('s')
        return 0.6 if w.endswith('or') else 1.4
    if w in {'calcul', 'calc'}:
        return 1.0
    if w == 'numerically':
        return 3.2
    if w == 'numerical':
        return 1.8
    if w == 'analytically':
        return 2.6
    if w.startswith('computa'):
        return 2.6 if w.endswith('ly') else 1.6
    if w in {'compute', 'computed', 'computes', 'comput'}:
        return 1.2
    if w in {'model', 'models', 'modeled', 'modelled', 'analysis', 'analyses',
             'analy', 'experimental', 'experiments', 'theoretical'}:
        return 1.0
    if w in {'modeling', 'modelling', 'analytical', 'derivation'}:
        return 1.5
    if w in {'solve', 'solves', 'solved', 'solving', 'solver', 'solvers'}:
        return 0.8
    if w == 'approximate':
        return 0.5
    if w.startswith(('estimat', 'predict', 'deriv', 'approximat')):
        if w == 'approximately':
            return 0.1
        return 0.65 if w.endswith('ed') else 0.8
    if w in {'observed', 'observations', 'measurements', 'mathematical',
             'fitting', 'fitted', 'results', 'quant', 'numer'}:
        return 0.7
    if w in {'answer', 'answers', 'formula', 'formulas', 'proof', 'prove',
             'obtain', 'obtained', 'determine', 'determined', 'determining',
             'observe', 'observation', 'measured', 'measurement', 'experiment',
             'algorithm', 'theory', 'perform', 'performed', 'statistical',
             'implementation', 'fit', 'accurate', 'exact'}:
        return 0.5
    if w in {'find', 'finding', 'findings', 'method', 'methods', 'approach',
             'study', 'studies', 'studied', 'solution', 'solutions', 'values',
             'parameters', 'equations', 'understand', 'understanding',
             'describe', 'described', 'evaluate', 'evaluation', 'comparison'}:
        return 0.35
    if w in {'result', 'found', 'code', 'value', 'equation', 'parameter',
             'consider', 'shown', 'evidence', 'design', 'defined'}:
        return 0.23
    return 0.12 if w == 'data' else 0.0


TRANSLATIONS = {'计算': 1.25, '模拟': 1.4, '模型': 0.85, '分析': 0.5,
                '代码': 0.55, '解决': 0.35, '结果': 0.35, '预测': 0.8}
SCIENTIFIC = frozenset("""numerical mathematical statistical computational
    theoretical experimental empirical scientific analytical quantitative
    linear nonlinear discrete stochastic quantum simulation simulations
    equation equations formula research analysis regression kinetic dynamics
""".split())


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    fragment, last = ('', '') if carry is None or carry[0] != doc else carry[1:]
    text = token.strip()
    english = text.isascii() and text.isalpha()
    joined = english and text == token and bool(fragment)
    word = fragment + text if joined else text
    w = word.lower()
    value = response(w) if english else TRANSLATIONS.get(text, 0.0)
    if english:
        if not value and response(text.lower()):
            value, joined = response(text.lower()), False
        if not joined:
            if not token.startswith(' '):
                value *= 0.2 if value < 0.8 else 0.6
            elif word[0].isupper():
                value *= 0.7
        if word[0].isupper() and w in {'calculate', 'compute'}:
            value *= 0.6
        if word.isupper():
            value *= 0.4
            if w in {'observation', 'action', 'thought'}:
                value = min(value, 0.1)
        if token.startswith(' ') and text.islower():
            value *= 1.6 if last in SCIENTIFIC else 1.0
            if last in {'to', 'we', 'can'}:
                value *= 1.2
            if w in {'model', 'models'} and last in {'language', 'business', 'ai'}:
                value *= 0.4
            if w == 'code':
                value = -0.04 if last in {'exit', 'status', 'error'} else 0.5
            if w == 'data' and last == 'experimental':
                value = 1.25
    return (doc, word if english else '', w), float(value)

"""Closing quotations and text/math/code delimiters.

A delimiter standing by itself after text has a much larger response than an
opening delimiter or one attached to punctuation. A recent matching opener,
the length of the preceding text fragment, and code-like punctuation refine
that distinction. A 500-character suffix and the previous token are kept,
resetting at document boundaries. Unrecognized tokens get zero. The rounded
weights were fitted to training activations. This is a typography heuristic,
not a language parser.
"""

READS = ()

# These marks can close a different-looking opener.
PAIRS = {'’': '‘', '“': '„', '«': '»'}

# Columns: bias, preceding letter/number, preceding digit, recent opener,
# preceding fragment length, code punctuation, length since last delimiter.
WEIGHTS = {
    '"': (0.50, 0.60, 0.00, 0.55, 0.65, -0.55, -0.20),
    "'": (-0.05, 0.30, 0.10, 0.85, 0.45, -0.15, -0.20),
    '`': (0.60, 0.35, 0.10, 0.60, 0.25, 0.00, -0.25),
    '$': (0.50, 0.40, -0.05, 0.70, -0.65, 0.10, -0.30),
    '$$': (1.30, 0.00, -0.10, 0.15, -0.50, 0.20, -0.25),
    '**': (0.30, 0.25, 0.00, 0.25, 0.40, 0.00, -0.10),
}


def features(mark, previous, tail):
    opener = PAIRS.get(mark, mark)
    i = tail.rfind(opener)
    span = tail[i + len(opener):] if i >= 0 else ''
    if opener == mark:
        j = i - 1
        while j >= 0 and tail[j] == '\\':
            j -= 1
        opened = i >= 0 and (j < 0 or
                    (not tail[j].isalnum() and tail[j] != mark))
    else:
        opened = i > tail.rfind(mark)
    if mark == '«' and i > 0 and tail[i - 1].isalnum():
        opened = False
    last = tail[-1:] or ' '
    code_like = (any(ch in span for ch in '_{}=\\/') or
                 (i >= 0 and tail[:i].rstrip()[-1:] in ('=', '(', '[', '{', ':')))
    return (1.0, float(last.isalnum()), float(last.isdigit()),
            float(opened), min(len(previous.strip()), 12) / 12,
            float(code_like),
            min(len(span), 40) / 40)


def response(token, previous, tail):
    last = tail[-1:] or ' '
    if token == '$' and last == '\\':
        return 0.0
    if token in WEIGHTS:
        if not tail:
            return 0.45 if token == "'" else 0.85 if token == '`' else 0.65
        if last.isspace():
            return -0.08 if token == "'" else 0.0
        f = features(token, previous, tail)
        return max(-0.2, sum(w * x for w, x in zip(WEIGHTS[token], f)))
    if token == '’':
        f = features(token, previous, tail)
        return 0.05 + 1.15 * f[3] + 0.3 * f[4] + 0.3 * f[2]
    if token == '“':
        return 1.65 if features(token, previous, tail)[3] else -0.12
    if token == '«':
        return 1.15 if features(token, previous, tail)[3] else -0.20
    if token in ('”', '»'):
        if last.isspace():
            return -0.12
        base = 1.55 if token == '”' else 1.20
        return base + 0.3 * min(len(previous.strip()), 12) / 12 \
            - 0.35 * last.isdigit() - 0.6 * (not last.isalnum())
    if token in ('」', '』', '》', '〉', '〞', '″'):
        return 0.70 if token in ('》', '〉', '〞', '″') else 0.95
    if token in ('「', '『', '„'):
        return -0.24 if token == '「' else -0.15
    if token in ('《', '〈'):
        return -0.04
    if len(token) >= 3 and set(token) == {'`'}:
        return -0.08
    if token == '``':
        return -0.07 if last.isspace() else 0.58 if last.isalnum() else 0.2
    if token == '*':
        return 0.28 if last.isalnum() else -0.03

    # Delimiters fused with adjacent punctuation are weaker.
    marks = '"\'`$”’»」』》〞'
    positions = [i for i, ch in enumerate(token) if ch in marks]
    if not positions:
        return 0.0
    i = positions[-1]
    mark = token[i]
    before, after = token[:i], token[i + 1:]
    if any(ch.isalnum() for ch in before + after):
        return 0.7 if mark in '”」』》' and not before else 0.0
    if len(positions) > 1:
        if all(ch in marks for ch in token):
            return 1.1 if '`' in token else 0.55
        return 0.0
    if before and (before[0].isspace() or
                   before.rstrip('\\').endswith(tuple('([{=:'))):
        return 0.4 if mark in '»”' else 0.0
    if after:
        if '\n' in after and not after.isspace():
            return -0.06
        if ')' in after or ']' in after or '}' in after:
            return 0.0
        if mark == '"':
            if ':' in after:
                return -0.04
            return 0.12 if after.isspace() or ',' in after else 0.22
        return 0.32 if mark in '$`”’»' else 0.03
    if before and set(before) == {'\\'}:
        return 0.5 * response(mark, previous, tail)
    if before.endswith(','):
        return 0.65 if len(before) == 1 else 0.15
    if before.endswith(tuple(')]}>')):
        return 0.90
    if before.endswith(tuple('.!?。！？')):
        return 0.38
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    value = response(token, previous, tail)
    return (doc, (tail + token)[-500:], token), float(value)

"""Surface-form detector centered on English 'be', not copulas in general.

