    elif token.isascii() and token.strip().lower() == "eta":
        value = 2.5
    elif now.startswith(before.rstrip("�")) and now[len(before.rstrip("�")):]:
        added = now[len(before.rstrip("�")):]
        if any(is_eta(c) for c in added):
            value = 5.0
        elif any(is_omega_iota(c) for c in added):
            value = 1.0
    elif any(is_omega_iota(c) for c in token):
        value = 1.0
    return carry, value

programs.sol:
"""Estimate structural negative pulses, with modest surface-form corrections.

Training shows nearly fixed negative pulses at chat, reasoning and tool markers.
Message starts are weaker at document starts; tool-message endings are stronger.
Other estimates use token form: compound identifiers, code punctuation/operators,
repeated spacing/separators, longer kana/Han fragments, and spelled-out tens.
These approximate regularities, not the many individual lexical responses.
"""
import re

READS = ()
BOUNDARIES = {
    '<|im_start|>': -2.16,
    '<|im_end|>': -2.72,
    '<think>': -2.25,
    '</think>': -1.76,
    '<tool_call>': -2.84,
    '</tool_call>': -2.92,
    '<tool_response>': -3.05,
    '</tool_response>': -3.51,
    '<|endoftext|>': -0.07,
}

TENS = frozenset(('twenty', 'thirty', 'forty', 'fifty',
                  'sixty', 'seventy', 'eighty', 'ninety'))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    start = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if token == '<|im_start|>':
        return None, -1.897 if start else -2.2
    if token == '<|im_end|>' and not start:
        previous = prefix.token_strings[-2]
        if previous == '</tool_call>':
            return None, -3.045
        if previous == '</tool_response>':
            return None, -2.87
        return None, -2.53
    if token in BOUNDARIES:
        return None, BOUNDARIES[token]
    word = token.strip()
    value = -0.004
    if word.lower() in TENS:
        return None, -0.75
    if '```' in token:
        return None, -0.43
    if word == '<<':
        return None, -0.46
    if re.search(r'"\[?%$', word):
        return None, -1.2 if '(' in word else -0.5
    if len(word) >= 16 and len(word) < 80 and len(set(word)) == 1:
        if not word[0].isalnum():
            return None, -0.85
    if token and not token.strip(' ') and len(token) >= 64:
        return None, -1.4
    if len(token) > 1 and not token.strip('\xa0'):
        return None, -0.17 * len(token)
    if token.endswith('\n') and not token.strip(' \n'):
        if token.count(' ') >= 12:
            return None, -0.4
    if len(token) > 1 and not token.strip('·'):
        return None, -0.42
    if word.isascii() and word.isalpha():
        if re.search('[a-z][A-Z]', word):
            value -= 0.073 * max(0, len(word) - 2)
    if len(word) > 1 and word[1:].isascii() and word[1:].isalpha():
        length = len(word) - 1
        if word[0] == '.':
            value -= 0.065 * max(0, length - 1)
        elif word[0] == '_':
            value -= 0.04 * max(0, length - 3)
        elif word[0] == '(':
            value -= 0.033 * max(0, length - 1)
        elif word[0] == '/':
            value -= 0.07
        elif word[0] == '[':
            value -= 0.11 * max(0, length - 1)
        elif word[0] == '<':
            value -= 0.065 * max(0, length - 1)
        elif word[0] == '@':
            value -= 0.65
    if word and all('\u3040' <= ch <= '\u30ff' or
                    '\u4e00' <= ch <= '\u9fff' for ch in word):
        value -= 0.13 * max(0, len(word) - 2)
    return None, value

"""A number-start detector, strongest on the first digit of a numeral.

Continuation digits are nearly silent. Decimal/comma groups, digit lists,
identifier suffixes, exponents and byte escapes have weaker starts. Indented
numbers are stronger. Ten small calibrations distinguish the digit shapes;
Unicode decimal digits are treated like their ordinary counterparts.
Subscript digits also respond; unfinished UTF-8 is resolved from decoded text.
"""
import unicodedata

READS = ()
DIGIT_STRENGTH = (1.53, 1.79, 2.03, 2.00, 1.89,
                  1.81, 1.68, 1.65, 1.61, 1.52)


def digit(token):
    return len(token) == 1 and token.isdecimal()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        _, previous, before = carry
    token = prefix.token_strings[-1]
    if '�' in token:
        completed = prefix.text_prefixes[-1][-1]
        if completed.isdigit():
            token = completed
    is_digit = digit(token)
    value = 0.003
    if len(token) == 1 and token in '₀₁₂₃₄₅₆₇₈₉':
        value = 0.4 if token == '₀' else (0.9 if token in '₁₂' else 1.55)
    if is_digit:
        n = unicodedata.decimal(token)
        value = DIGIT_STRENGTH[n]
        p = previous.strip()
        if previous and previous[-1].isdecimal():
            value = 0.0
        elif p.endswith('^'):
            value = 0.5 if n == 1 else (-0.16 if n == 2 else 0.25)
        else:
            if p in ('.', ','):
                value -= 0.68
            if '\\x' in (before + previous)[-5:]:
                value -= 1.34
            elif len(p) == 1 and p.isascii() and p.isalpha():
                value -= 1.07
            if len(p) > 1 and p.isascii() and p[-1].isalpha():
                value -= 0.66
            if p.endswith('**'):
                value -= 0.75
            if p.endswith('^{') or p.endswith('^('):
                value -= 0.9
            if p in ('_', '_{'):
                value -= 0.45
            if p in ('=', '+', '*', '×', '≈'):
                value -= 0.29
            if previous.isspace():
                if before.isspace() and len(before) > 1:
                    value += 0.48
                if digit(before) and '\n' not in previous:
                    value -= 0.66
                if before == '.':
                    value -= 0.15
    return (doc, token, previous), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:1681: a "first digit of a number" detector.

It fires on the first digit of a number (a digit not preceded by another digit), e.g. the
"3" in "x = 3.5" or the "1" in "1990". It stays silent on the later digits of a number.
How strongly it fires depends on the token just before the digit:
  - after a space, bracket, newline, operator or at the start of a document: strong (1.8);
  - after a comma or period: weaker (1.0);
  - after a letter (a digit attached to a word, as in "x2"): weaker (0.7);
  - after a number followed by a space ("0 1"): weaker (0.8);
  - after "^" or a backslash escape such as "\\x": off (0).
Everything else is 0. The values are the typical activations; the program reads only the
current token and the one or two before it.
"""

READS = ()
DIGITS = set("0123456789")
ESCAPE_OR_POWER = {"^", "\\x", "\\xa", "\\xc", ")^"}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    if s[-1] not in DIGITS:
        return None, 0.0
    # First token of a document: nothing before it, so treat as a number start.
    if len(s) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 1.8
    before = s[-2]
    if before in DIGITS or before in ESCAPE_OR_POWER:
        return None, 0.0  # later digit of a number, or after ^ / an escape
    if before in (".", ","):
        return None, 1.0
    if before.isalpha():
        return None, 0.7
    if before == " " and len(s) > 2 and s[-3] in DIGITS:
        return None, 0.8  # a number right after another number and a space
    return None, 1.8

programs.sol:
"""Approximate a detector for short, u-like token endings.

Training positives are dominated by short Cyrillic fragments ending у/ю.
Leading whitespace and longer fragments usually weaken their response;
nasal-consonant endings (му/ну) are stronger and soft-sign endings (ью) weaker.
Smaller rules cover other Cyrillic inflections, Latin u/ogonek vowels,
and selected Japanese, Greek and Arabic spellings. Everything else is zero.
Only the current token is used, so contextual variation is not modeled.
"""
READS = ()

ADVERBS_AND_PREPOSITIONS = {
    'между', 'почему', 'поэтому', 'потому', 'поскольку', 'полностью',
}
CASE_PRONOUNS = {'эту', 'ту', 'всю', 'этому', 'тому'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    s = word.lower()
    n = len(s)
    spaced = token[:1].isspace()
    p = 0.0
    if not n:
        return None, p
    if all('а' <= c <= 'я' or c == 'ё' for c in s):
        if s.endswith(('у', 'ю')):
            if s in ADVERBS_AND_PREPOSITIONS:
                p = 0.1
            elif s.endswith('ью'):
                p = 1.4 if n == 2 and not spaced else 0.2
            elif spaced:
                if s == 'у':
                    p = 2.1
                elif s in CASE_PRONOUNS:
                    p = 3.4
                elif s == 'ну':  # Discourse particle, not a suffix.
                    p = 3.1
                else:
                    p = 1.3 if n < 7 else 0.6
            elif n == 1:
                p = 4.9 if s == 'у' and not word.isupper() else 3.3
            elif s.endswith('ю'):
                p = 3.7 if n <= 3 else 2.4
            elif s[-2] in 'мн' and n <= 4:
                p = 4.8 if n <= 3 else 4.1
            else:
                if n == 2:
                    p = 4.2 if s[-2] in 'рл' else 3.4
                else:
                    p = 3.0 if n <= 4 else 1.1
        elif s == 'по':
            p = 0.98
        elif not spaced:
            if s.endswith(('ам', 'ям', 'ым')):
                p = 1.05
            elif s == 'м' or s.endswith('им'):
                p = 0.5
            elif s.endswith('ом'):
                p = 0.4
            elif s.endswith('нуть'):
                p = 1.1
            elif s.endswith('ировать'):
                p = 0.7
            elif s == 'ся':
                p = 0.35
            elif s == 'ке':
                p = 0.45
            elif s.endswith('ое'):
                p = 0.85
            elif s.startswith('у') and n == 2:
                p = 0.55
            elif s.endswith(('ния', 'ний', 'ки', 'ных')):
                p = -0.25
    elif s.endswith(('ę', 'ą')):
        if s != 'się':
            p = (3.4 if n == 1 else 2.0) if s[-1] == 'ę' else 1.5
            p *= 0.5 if spaced else 1.0
    elif s.endswith(('ü', 'ú', 'ů', 'ű', 'û')):
        p = 0.35 if s[-1] in 'ůűû' else 0.75
    elif s.endswith('u') and s.isalpha() and not word[:1].isupper():
        if not s.endswith(('au', 'ou', 'eu', 'qu')):
            p = 0.2 if spaced else (0.5 if n <= 2 else 0.9)
    elif word in {'く', 'ぐ', 'ク', 'ウ', 'ゥ', 'キュ', 'ミュ', 'チュ', 'ュ'}:
        p = 0.8
    elif n <= 3 and word.endswith(('く', 'ぐ')):
        p = 0.5
    elif word in {'む', 'ぶ', 'ず', 'す', 'る'}:
        p = 0.35
    elif token in {'υ', 'ύ', 'ϋ', 'و'}:
        p = 0.35
    return None, float(p)

