"""Look for rounded-vowel subword pieces, with a small multilingual fallback."""

import unicodedata

READS = ()
U_LIKE = set("uüúùûūůűųуұүӯўюӱӳʉʊ")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    if any(char in U_LIKE for char in token):
        return None, 0.08
    if any(ord(char) > 127 and unicodedata.category(char).startswith("L")
