programs.sol:
"""A spelling-level detector for books and related reading/media words.

Book(s) is strongly negative, with differences for case and token boundaries.
Book compounds, translations, and spelling fragments respond more weakly;
fragments also match unrelated words. Other reading materials are weaker still.
One-token phrase rules cover comic/scrap book, book of, BOOK+S and of course.
All other tokens predict zero. The previous token resets between documents.
"""
READS = ()

# Related words grouped by approximate response strength, not by token IDs.
LEXICAL = {}
for strength, words in (
    (-5.5, 'textbook textbooks'),
    (-4.5, 'ebook ebooks cookbook booklet'),
    (-3.6, 'workbook handbook notebook'),
    (-2.5, 'paperback bookstore notebooks'),
    (-2.0, 'booking booker'),
    (-3.1, 'booked'),
    (-0.7, 'bookmark movie movies'),
    (-4.2, 'libro livro buch кни 本書 本书 图书 书籍'),
    (-3.0, 'libros bücher книг книги kitabı 북 一本 这本书 教材'),
    (-2.3, 'livre livres 书 册 读书 书中'),
    (-1.5, '本 書 籍 文书 الكتاب novel novels album'),
    (-4.5, '簿'),
    (-1.1, 'albums bible memoir manuals ook liv'),
    (-2.4, 'isbn bü'),
    (-1.0, 'chapter chapters álbum'),
    (-0.8, 'paper papers paperwork sheet sheets worksheets guide guides '
            'manual manuscript course uch'),
    (-0.6, 'literature publication publications journal newspaper newspapers '
            'magazine magazines pdf courses'),
    (-0.45, 'library'),
    (-0.5, '章'),
    (-1.6, 'ooks'),
    (-6.9, 'obook'),
):
    LEXICAL.update(dict.fromkeys(words.split(), strength))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._-/(<').rstrip(')')
    lower, prev = word.lower(), previous.strip().lower()
    value = LEXICAL.get(lower, 0.0)
    if lower in ('book', 'books'):
        if lower == 'books':
            value = -5.3 if token.startswith(' ') else -6.0
            if word == 'Books':
                value = -5.0
        elif word.isupper():
            value = -8.4
        elif word == 'Book':
            value = -7.8
        else:
            value = -6.2 if token.startswith(' ') else -8.1
        if token.startswith(('.', '_', '(', '<', '-', '/')):
            value *= 0.55 if token[0] in '(<' else 0.8
        if prev == 'comic':
            value *= 0.57
        elif prev == 'scrap':
            value = -4.2
    elif lower == 'of':
        if previous.strip() == 'Book':
            value = -4.1
        elif prev in ('book', 'handbook', 'textbook'):
            value = -2.6
        elif prev == 'books':
            value = -1.6
        elif prev == 'album':
            value = -1.0
    elif word == 'S' and previous.strip() == 'BOOK':
        value = -3.8
    elif word == 'OOK':
        value = -3.2
    elif lower == '책':
        value = -3.5 if token.startswith(' ') else -0.7
    elif lower == 'buch' and token.startswith(' '):
        value = -3.1
    elif lower == 'album' and not token.startswith(' '):
        value = -0.9
    elif lower == 'course' and prev == 'of':
        value = -0.33
    return (doc, token), float(value)

