"""Detect book/publishing vocabulary and shrink its rough activation estimate."""

READS = ()

BOOKS = {
    "book", "books", "ebook", "ebooks", "textbook", "textbooks",
    "storybook", "storybooks", "libro", "libros", "livre", "livres",
    "buch", "bucher", "buchs", "книга", "книги", "本",
}
WRITTEN_WORKS = {
    "paper", "papers", "publication", "publications", "literature",
    "journal", "journals", "magazine", "magazines", "album", "albums",
    "chapter", "chapters", "worksheet", "worksheets", "document",
    "documents", "manuscript", "manuscripts", "passport", "passports",
    "library", "libraries", "classics", "volume", "volumes", "文书", "章",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = carry[1] if carry is not None and carry[0] == doc else ""
    score = 0.0
    for char in prefix.token_strings[-1]:
        if char.isalpha():
            word += char.lower()
        else:
            if word in BOOKS:
                score = -5.5
            elif word in WRITTEN_WORKS:
                score = -0.7
            word = ""
    if word in BOOKS:
        score = -5.5
    elif word in WRITTEN_WORKS:
        score = -0.7
    return (doc, word[-32:]), float(0.6 * score)

programs.sol:
"""Approximate a multilingual i-spelling feature.

Single yeh letters and Thai/Indian i vowel signs are strongest. Longer
pieces containing yeh are weaker; Greek iota weakens after another vowel.
There are smaller responses to other i spellings and Indian e signs.
Byte-split characters are recovered, with a negative split-long-s rule.
Most other text receives zero; this is not a pronunciation model.
"""
import unicodedata as ud

READS = ()

# i-like letters and syllables, with different strengths by writing system.
I_FORMS = (
    ('იի', 1.5),       # Georgian and Armenian i
    ('î', 1.0),
    ('ī', 1.3),
    ('ɪי', 0.65),      # Phonetic small-cap i and Hebrew yod
    ('ِ', 0.68),        # Arabic short-i mark
    ('ί', 0.7),
    ('Ι', 0.55),
    ('ῖ', 0.45),
    ('і', 0.2),
    ('И', -0.22),
    ('íïİ', 0.12),
    ('イビシチヒじ', 0.3),
    ('飞飛', 0.6),       # Chinese fei
    ('利里尼米维皮费', 0.3),  # Common Chinese i/ei-rime characters
)


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    split = '�' in raw
    same_doc = (prefix.position > 0 and
                prefix.document_ids[-2] == prefix.document_ids[-1])
    s = raw.replace('�', '').strip()
    if split and not s and same_doc:
        s = prefix.text_prefixes[-1][-1:].replace('�', '')
    if split and s == 'ſ':
        return None, -0.97
    s = ud.normalize('NFKC', s)
    if not s:
        return None, 0.0

    if any(c in s for c in 'یي'):
        if len(s) == 1:
            value = (0.72 if raw[:1].isspace()
                     else (2.27 if s == 'ی' else 1.92))
        elif 'ی' in s:
            value = (0.45 if s.endswith('ی') else 0.35) * 2 / len(s)
        elif len(s) == 2:
            value = 1.02 if s.endswith('ي') else 0.65
        else:
            value = 1.5 * s.count('ي') / len(s)
        return None, value
    if s == 'ى':
        return None, 1.2
    if any(c in s for c in 'ีิ'):
        value = (2.9 if s == 'ี' else 1.55) if len(s) == 1 else 0.4
        return None, value

    # Indian scripts: Devanagari through Sinhala.
    for c in s:
        if not '\u0900' <= c <= '\u0dff':
            continue
        name = ud.name(c, '')
        if name.endswith('VOWEL SIGN II'):
            return None, 4.4 / len(s)
        if name.endswith('VOWEL SIGN I'):
            value = 3.5 if split else (1.95 if c == 'ि' else 3.4)
            return None, value / len(s)
        if name.endswith(('VOWEL SIGN E', 'VOWEL SIGN EE')):
            value = 1.7 if split or 'BENGALI' in name else 0.6
            return None, value / len(s)

    if len(s) == 1:
        if s == 'ι':
            prev = prefix.token_strings[-2].strip() if same_doc else ''
            prev = ''.join(c for c in ud.normalize('NFD', prev)
                           if not ud.combining(c))
            value = 0.85
            if same_doc:
                value = 0.58 if prev and prev[-1] in 'αεηιοωυ' else 1.0
            return None, 0.4 if split else value
        if s == 'и':
            return None, -0.03 if raw[:1].isspace() else 0.16
        if s == 'リ':
            return None, 0.35 if split else 0.62
        if s == '西':  # Chinese west, pronounced xi
            return None, 2.25 if split else 1.47
        if '\uac00' <= s <= '\ud7a3' and ((ord(s) - 0xac00) // 28) % 21 == 20:
            return None, 0.5 if s in '리시디티' else 0.25
        for letters, value in I_FORMS:
            if s in letters:
                return None, value
    return None, 0.0

"""Approximate an -ack spelling detector, with lack the strongest whole word.
Inflections weaken it, but 'lack of' continues strongly onto 'of'. Back,
black and package are deliberately not treated as active -ack words.
Short ck fragments and several lack translations also respond. README
is an extra negative response and business an extra positive one.
Current spelling and strength are carried across tokens, reset by document.
"""
import re

READS = ()
ACK_FAMILIES = (
    (6.0, {'lack'}),
    (4.7, {'pack', 'hack', 'tack', 'mack'}),
    (3.1, {'jack', 'rack', 'sack', 'crack', 'slack'}),
    (2.0, {'attack'}),
    (1.6, {'track', 'stack', 'snack', 'backpack', 'unpack'}),
)
ENDINGS = {'': 1.0, 's': 0.85, 'ed': 0.60,
           'ing': 0.70, 'er': 0.68, 'ers': 0.68}
ACK_PIECES = {'ack': 6.7, 'acks': 4.9, 'acker': 3.5,
              'ackers': 3.2, 'acked': 3.0, 'acking': 4.0, 'acky': 2.6}
OF_PHRASES = {'lack': 4.0, 'absence': 0.9, 'loss': 0.6,
              'devoid': 0.6, 'shortage': 0.6, 'attack': 0.8}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, strength = carry[1:] if carry and carry[0] == doc else ('', 0.0)
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    spelling = word.lstrip('._/()-')
    value = -ACK_PIECES.get(word, 0.0)
    for amplitude, roots in ACK_FAMILIES:
        for root in roots:
            if spelling.startswith(root) and spelling[len(root):] in ENDINGS:
                factor = 1.0 if root == 'attack' else ENDINGS[spelling[len(root):]]
                value = -amplitude * factor
    if word == 'ack':
        if token.startswith(' '):
            value = -5.6
        elif token == 'Ack':
            value = -5.2
        elif tail.endswith(('h', 'j')):
            value = -5.5
        elif tail.endswith(('sl', 'tr')):
            value = -4.4
    elif word.startswith('acknowled'):
        value = -1.4 if len(word) > 10 else -3.5
    elif word == 'lacking':
        value = -3.1
    elif word == 'lacked':
        value = -4.4
    elif spelling == 'pack' and not token.startswith((' ', '.')):
        value = -5.2
    elif word in {'ck', 'cke', 'cken', 'cker', 'uck', 'ück'}:
        value = -0.8
    elif word in {'ick', 'ock', 'ек'}:
        value = -0.5
    elif word == 'nick':
        value = -1.4
    elif word in {'ッ', 'ック', '랙'}:
        value = -1.4
    elif word in {'absence', '缺', '欠', 'falta'}:
        value = -1.4
    elif word == '缺乏':
        value = -4.2
    elif word == '乏':
        value = -2.8
    elif word == 'readme':
        value = -1.05 if token.startswith(' ') else -0.56
    elif word == 'business':
        value = 0.6
    elif word == 'of':
        value = -OF_PHRASES.get(tail, 0.0)
    elif token.lower() in {'s', 'ed', 'ing', 'er', 'ers'} and tail.endswith('ck'):
        value = -0.45 * strength
    elif word == 'nowled' and tail.endswith('ack'):
        value = -2.1
    match = re.search(r'[A-Za-z]+$', tail + token)
    tail = match.group().lower()[-40:] if match else ''
    return (doc, tail, max(0.0, -value)), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:1686: an "-ack" word detector.

The component goes negative on the spelling "-ack" in words such as lack, pack, hack,
rack, tack and ACK: about -6 on the bare word, about -4 on its plurals and -ed/-er/-ing
forms. Weaker, about -3, on Jack, sack, slack, smack, crack, shack, knack. It is more
weakly negative on the attack family (about -2), on track and stack (about -1.5), on
other "-ck" words (deck, sock, nick, about -1), and on words for "lack" in other
languages (缺乏, thiếu, falta). It is also negative on the "of" right after "lack".
Its one clear positive response is a weak one on "business" (+0.6). Every other token
predicts 0.
"""

READS = ()

STRONG = {"ack", "lack", "pack", "hack", "rack", "tack"}
MEDIUM = {"jack", "sack", "slack", "smack", "crack", "shack", "knack", "nack", "zack", "mack"}
CK = {"deck", "sock", "nick", "buck", "suck", "kick", "chuck", "dick"}
LACK_OTHER = {"缺乏", "缺少", "欠缺", "短缺", "匮乏", "缺", "欠", "thiếu", "falta", "absence"}
SUFFIXES = ("s", "ed", "er", "ers", "ing")


def in_family(word, stems):
    """True for a stem itself or a stem with a plural, past, agent or -ing ending."""
    if word in stems:
        return True
    for suffix in SUFFIXES:
        if word.endswith(suffix) and word[: -len(suffix)] in stems:
            return True
    return False


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].lower().strip(" .-_()[]\t\n")
    value = 0.0
    if word in STRONG:
        value = -6.0
    elif in_family(word, STRONG):
        value = -4.0
    elif in_family(word, MEDIUM):
        value = -3.0
    elif in_family(word, {"attack"}):
        value = -2.2
    elif in_family(word, {"track"}):
        value = -1.5
    elif in_family(word, {"stack", "snack"}):
        value = -1.3
    elif word in CK or "ック" in word:
        value = -1.0
    elif word in LACK_OTHER:
        value = -3.0
    elif word == "business":
        value = 0.6
    if word == "of" and len(prefix.token_strings) > 1:
        same_doc = prefix.document_ids[-2] == prefix.document_ids[-1]
        if same_doc and prefix.token_strings[-2].lower().strip() == "lack":
            value = -4.0
    return carry, float(value)

programs.sol:
"""A lexical test/try detector, with a separate positive Korea response.

Negative triggers include testing, attempts, trials, interviews, and Chinese
assessment words. Lone test characters are especially strong. Spelling,
capitalization, code-name punctuation and preceding indentation change the
strength. Japanese '験' is recognized when its final bytes complete it.

Everything else predicts zero. The two-character carry resets at document
boundaries; decoded text is consulted only for split or Chinese characters.
This explains the lexical peaks, not the many small background fluctuations.
"""
READS = ()

ASSESSMENT = {
    'test': -0.68, 'tests': -0.68, 'tested': -1.06,
    'testing': -1.20, 'try': -0.56, 'tries': -0.77,
    'tried': -1.02, 'trying': -1.32,
    'trial': -1.00, 'trials': -1.04,
    'attempt': -0.13, 'attempts': -0.62,
    'attempted': -0.65, 'attempting': -0.69,
    'interview': -1.24, 'interviews': -1.15,
    'interviewed': -0.93, 'interviewing': -1.32,
    'diagnostic': -0.60, 'diagnostics': -0.50,
    'screening': -0.50, 'exam': -0.40, 'exams': -0.50,
    'examine': -0.23, 'examined': -0.13, 'examining': -0.21,
    'examination': -0.26, 'examinations': -0.23,
    'experimental': -0.22, 'experimenting': -0.74,
    'troubleshooting': -1.10, 'phpunit': -0.83, 'junit': -0.81,
    'тест': -0.66,
}
# For these forms: bare lowercase, spaced capitalized, bare capitalized.
SPELLING = {
    'test': (0.01, -0.45, -0.20),
    'tests': (-0.36, -0.68, -0.20),
    'testing': (-0.42, -0.75, -0.75),
    'trying': (-0.79, -1.12, -0.89),
    'try': (-0.18, -0.36, -0.48),
    'tries': (-0.16, -0.77, -0.16),
}
# Trying, retesting, examinations, experiments and interviews.
CHINESE_ASSESSMENT = {
    '试': -5.93, '試': -5.35, '考': -0.45,
    '复试': -3.71, '複試': -3.71, '试试': -4.14, '試試': -4.14,
    '试图': -1.08, '試圖': -1.08, '试管': -0.93, '试点': -0.57,
    '考试': -2.44, '考試': -1.84, '测试': -0.90, '測試': -1.10,
    '试验': -1.54, '試驗': -1.54, '验': -0.35, '驗': -0.59,
    '尝试': -1.01, '嘗試': -1.01, '面试': -2.54,
}
KOREA = {
    '韩': 3.53, '韓': 3.40, '韩国': 1.54, '韓國': 1.54,
    '한국': 0.78, 'Korean': 0.79, 'Koreans': 0.38, 'Korea': 0.21,
}


def english_response(token, previous):
    word = token.strip()
    letters = word.lstrip('/-._([@')
    mark = word[:len(word) - len(letters)]
    form = letters.lower()
    value = ASSESSMENT.get(form, 0.0)
    spaced = token.startswith(' ')
    if form in SPELLING:
        bare, title, bare_title = SPELLING[form]
        if letters.istitle():
            value = title if spaced else bare_title
        elif not spaced:
            value = bare
    if form in ('test', 'tests'):
        if mark == '/':
            value = -0.10 if form == 'test' else -0.92
        elif mark == '-':
            value = -0.40
        elif mark in ('_', '.') and letters.islower():
            value = 0.04
    if spaced and previous.endswith(('  ', '\t', '\n')):
        # An indented test name or try statement, rather than ordinary prose.
        if form == 'test':
            value = -0.23 if letters.istitle() else -0.13
        elif form == 'tests':
            value = -0.32
        elif form == 'try':
            value = -0.23
        elif form == 'testing':
            value = -0.44
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    if word in CHINESE_ASSESSMENT:
        value = CHINESE_ASSESSMENT[word]
        if word == '試' and previous:
            preceding_character = prefix.text_prefixes[-2][-1:]
            if preceding_character in ('測', '考'):
                value = -2.0
            elif preceding_character == '嘗':
                value = -3.30
    elif word in KOREA:
        value = KOREA[word]
    elif '\ufffd' in token and prefix.text_prefixes[-1].endswith('験'):
        value = -1.20
    else:
        value = english_response(token, previous)
    return (doc, (previous + token)[-2:]), float(value)

programs.haiku:
"""Layer 0 MLP down-projection component 1687: a "test / try / trial" word detector.

The component reads the current word and goes negative when that word means a test,
trial or try: the Chinese 試/试 ("test, try") most strongly, then English "trying",
"trial", "tested", "tests", "interview" (about -1.1), then "test", "try", "testing",
"attempting", "diagnostic", "screening" (about -0.6), and weakly "attempt", "exam"
(about -0.3). Everything else predicts 0. It looks only at the current token and
ignores context, so the bare word "test" in a file path or identifier (no leading
space) is predicted at a much smaller size than the spaced word in prose.
"""

READS = ()

CHINESE_TEST = ("試", "试")                  # test / try in Chinese: strongest
CHINESE_EXAM = ("考試", "考试", "测试", "測試")  # exam / test compounds
STRONG_WORDS = {
    "trying", "trial", "trials", "tried", "testing", "tested",
    "tests", "interview", "interviews",
}
MEDIUM_WORDS = {
    "test", "try", "tries", "attempting", "attempts", "diagnostic", "diagnostics", "screening",
}
WEAK_WORDS = {"attempt", "exam", "exams", "examination"}
BARE_WORDS = {"test", "tests", "testing", "tested", "try", "trying", "trial"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if token.strip() in CHINESE_TEST:
        return carry, -5.5
    if token.strip() in CHINESE_EXAM:
        return carry, -1.5
    if token.startswith(" ") or token == "/tests":
        if word in STRONG_WORDS or token == "/tests":
            return carry, -1.1
        if word in MEDIUM_WORDS:
            return carry, -0.6
        if word in WEAK_WORDS:
            return carry, -0.3
    elif word in BARE_WORDS:
        # no leading space: usually a path, identifier or compound piece
        return carry, -0.3
    return carry, 0.0

"""Layer-0 MLP down_proj component 1690: a weak, mostly token-level feature.

What it does: predicts the component's activation from the kind of the current token,
using a few coarse character classes. Its real activation is diffuse: it is small and
noisy (RMS about 0.036) and changes sign across tokens of the same class. Its largest
values sit on particular rare words, which no simple class captures.

Predictions (activation units):
  - a dotted code identifier such as ".getItem" or ".Printf" (member access, library
    names): slightly negative, -0.008;
  - Hangul or Arabic script: slightly positive, +0.01 and +0.007;
  - CJK ideographs or kana: +0.0015;
  - a word piece with no leading space (a continuation of a word): +0.0025;
  - everything else: 0.
"""

READS = ()

DOTTED = {"hangul": 0.01, "arabic": 0.007, "cjk": 0.0015, "kana": 0.0015}


def _script(ch):
    code = ord(ch)
    if 0xAC00 <= code <= 0xD7AF:
        return "hangul"
    if 0x0600 <= code <= 0x06FF:
        return "arabic"
    if 0x3040 <= code <= 0x30FF:
        return "kana"
    if 0x4E00 <= code <= 0x9FFF:
        return "cjk"
    return None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    value = 0.0
    if not text:
        value = 0.0
    elif token.startswith(".") and text[1:].replace("_", "").isalpha():
        value = -0.008
    elif _script(text[0]) is not None:
        value = DOTTED[_script(text[0])]
    elif text.isalpha() and text.isascii() and not token.startswith(" "):
        value = 0.0025
    return carry, float(value)

programs.sol:
"""Approximate a prose-to-symbol transition detector.

A single Latin letter, Greek letter/name, formula opener, or short geometric
label gets a positive response after words that introduce mathematical
objects or conditions. Letters following other letters/numbers get little
response. 'a' and 'I' are usually prose, so have separate rules. Formula
openers also cue the next unspaced letter. Small letter-specific adjustments
calibrate strengths. Everything else is near zero; no mathematics is solved.
Scores are fitted to training activations; no token-id table is used.
The memory is the last 80 characters of token strings, reset per document.
"""
import re
READS = ()
BIND = set('let denote define choose set consider take suppose assume'.split())
LOGIC = set('if where when whenever since then so thus hence therefore unless '
            'that implies yields gives satisfies'.split())
MATH_NOUNS = set('variable integer number point matrix vector equation polynomial '
                 'function coordinate vertex element value parameter constant '
                 'length size interval region root exponent prime angle triangle '
                 'radius height mass ratio node distance space velocity product '
                 'speed relation probability midpoint coefficient array solution '
                 'subset sequence partition operator difference expression '
                 'direction configuration voltage temperature'.split())
MATH_ACTION = set('compute find factor write substitute substituting setting '
                  'solve pick satisfy divides equals calculate determine '
                  'express requires require need denote'.split())
MATH_OTHER = set('line time group form case sum position force area field '
                 'term degree column order range letter circle signal axis '
                 'formula map graph row side center output step part surface '
                 'volume energy current dimension subspace slope component '
                 'magnitude intersection domain range boundary edge index '
                 'tensor integral derivative gradient displacement pressure '
                 'density charge amplitude resistance momentum basis rank '
                 'segment diagonal orbit ring module ideal codomain image '
                 'preimage'.split())
QUANTIFIERS = set('all each any both some every either'.split())
DISCOURSE = set('but along possible than which wait maybe exactly because '
                'given large minimal perhaps after becomes least around '
                'assuming here exists first second third next last finally '
                'similarly alternatively recall remember meaning means equal '
                'needed become having only also not use get holds obtain even '
                'still whether result conclusion'.split())
PROSE_REL = set('of for at by with between from to in on into over under '
                'through using about like within while as'.split())
COPULA = set('is be are was were being been has have had'.split())
DETERMINERS = set('the a an this these those'.split())
CODE = set('int float double char string bool void return class public private '
           'static unsigned struct enum const'.split())
GREEK = set('alpha beta gamma delta epsilon zeta eta theta iota kappa lambda '
            'mu nu xi omicron pi rho sigma tau upsilon phi chi psi omega'.split())


WORD_CLASSES = (
    ('binding', BIND), ('logic', LOGIC), ('math_noun', MATH_NOUNS),
    ('math_action', MATH_ACTION), ('math_other', MATH_OTHER),
    ('quantifier', QUANTIFIERS), ('discourse', DISCOURSE),
    ('relation', PROSE_REL), ('copula', COPULA),
    ('determiner', DETERMINERS), ('code', CODE), ('greek_word', GREEK),
)


def previous_context(before):
    if not before:
        return 'start'
    match = re.search(r'([A-Za-z]+)$', before)
    word = match[1].lower() if match else ''
    if word in ('and', 'or'):
        return word
    for label, words in WORD_CLASSES:
        plural = label in ('math_noun', 'math_other') and word.endswith('s')
        if word in words or (plural and word[:-1] in words):
            if label == 'relation' and word in ('of', 'for', 'at', 'in', 'to'):
                return word
            if word == 'a':
                return 'article_a'
            return label
    if word:
        return 'letter' if len(word) == 1 else 'word'
    if before[-1].isdigit():
        return 'number'
    if before.endswith(('\\(', '\\[', '$')):
        return 'math_open'
    for label, endings in (
        ('comma', ','), ('colon', ':'), ('comparison', '=<>'),
        ('arithmetic', '+-*'), ('close', ')]}'),
    ):
        if before[-1] in endings:
            return label
    return 'space' if before[-1].isspace() else 'other'


def token_kind(token):
    s = token.strip()
    spaced = token.startswith(' ')
    if len(s) == 1 and s.isascii() and s.isalpha():
        if not spaced:
            return 'bare_letter'
        if s in ('a', 'I'):
            return s
        return 'ieo' if s in 'ieo' else 'lower' if s.islower() else 'upper'
    if token == ' ':
        return 'blank'
    if spaced and 2 <= len(s) <= 4 and set(s) <= set('ABCDEF'):
        return 'geometric_label'
    if spaced and s in ('sqrt', 'sin', 'cos', 'tan', 'cot', 'log', 'ln', 'exp'):
        return 'math_function'
    if spaced and s in ('(', '['):
        return 'paren' if s == '(' else 'bracket'
    if s in ('$', '$$', '\\', '\\(', '\\[', '$\\', '$(', '${'):
        return 'math_delimiter' if spaced else 'bare_delimiter'
    if len(s) == 1 and ('\u0370' <= s <= '\u03ff' or s in 'µℕℤℚℝℂℙ'):
        return 'greek' if spaced else 'bare_greek'
    if s.lower() in GREEK:
        return 'greek_name'
    return 'partial_character' if spaced and s == '\ufffd' else ''

# How strongly the preceding text suggests that a symbol comes next.
CONTEXT_SCORE = {
    'binding': 2.03, 'logic': 1.57, 'math_noun': 2.31,
    'math_action': 1.75, 'math_other': 1.60, 'quantifier': 1.58,
    'discourse': 1.40, 'copula': 1.21, 'relation': 1.09,
    'for': 1.32, 'at': 1.28, 'of': 1.04, 'to': 0.82, 'in': 0.70,
    'and': 1.03, 'or': 0.61, 'determiner': 0.40, 'article_a': -0.28,
    'word': 0.27, 'code': 0.36, 'greek_word': -0.05,
    'comma': 0.37, 'colon': 0.45, 'comparison': 0.32,
    'arithmetic': 0.14, 'math_open': 1.69, 'close': -0.03,
    'number': -0.12, 'letter': -0.13, 'space': 0.06,
    'other': 0.17, 'start': -0.08,
}


def response(kind, context):
    score = CONTEXT_SCORE[context]
    if kind == 'lower':
        return score
    if kind == 'upper':
        return (0.7*score - 0.04 + 0.6*(context == 'math_noun')
                + 0.12*(context == 'word') - 0.08*(context == 'other'))
    if kind == 'ieo':
        return 0.63*score - 0.1
    if kind == 'a':
        return {
            'math_noun': 1.4, 'math_other': 0.4, 'math_open': 1.0,
            'logic': 0.48, 'binding': 0.45, 'quantifier': 0.4,
            'of': 0.13, 'for': 0.16, 'at': 0.08, 'comparison': 0.21,
            'in': -0.09, 'number': -0.10, 'start': -0.18,
        }.get(context, 0.01)
    if kind == 'I':
        return {'math_noun': 0.6, 'binding': 0.5,
                'math_other': 0.2, 'for': 0.2}.get(context, 0.0)
    if kind in ('paren', 'bracket'):
        if context in ('math_noun', 'math_other', 'binding', 'math_action'):
            return 0.55
        if context in ('copula', 'at'):
            return 0.65
        if context in ('of', 'to', 'in', 'relation'):
            return 0.35
        return 0.1 if context in ('word', 'and', 'determiner') else 0.0
    if kind == 'math_delimiter':
        return (0.55*score - 0.05 + 0.35*(context == 'word')
                - 0.6*(context == 'math_open'))
    if kind == 'partial_character':
        return 0.8*score - 0.15*(context == 'other') - 0.6*(context == 'math_open')
    if kind == 'greek':
        return score + 0.6*(context == 'word') - 0.15*(context == 'other')
    if kind == 'bare_greek':
        return 0.0 if context in ('other', 'letter') else 0.2
    if kind == 'greek_name':
        return 0.3 if context == 'other' else 0.35*score
    if kind == 'bare_letter':
        return 1.3 if context == 'math_open' else 0.0
    if kind == 'bare_delimiter':
        return 0.65 if context == 'math_open' else 0.2 if context == 'space' else 0.05
    if kind == 'geometric_label':
        return 0.4*score
    if kind == 'math_function':
        return 0.4*score
    if kind == 'blank':
        if context == 'math_noun':
            return 0.38
        if context in ('binding', 'math_action'):
            return 0.27
        return 0.18 if context == 'logic' else 0.01
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    kind = token_kind(token)
    value = response(kind, previous_context(before)) if kind else 0.0
    # Calibrate especially strong and weak letter responses.
    s = token.strip()
    if kind in ('lower', 'upper'):
        if s in 'qxu':
            value += 0.28
        elif s in 'QXSN':
            value += 0.18
        elif s == 'l':
            value -= 0.25
        elif s in 'WJO':
            value -= 0.15
    elif kind == 'bare_letter' and token == 'x':
        value += 0.15
    return (doc, (before + token)[-80:]), float(value)

"""Estimate whitespace/script-boundary pulses, not word meanings.

Space-prefixed Han/kana gets a negative pulse after Han/kana, positive after
ASCII. Bare spaces after Han, kana or Thai also get strong negative values.
Already-spaced words and byte fragments modulate these predictions. Guess an
undecodable space-prefixed character from the latest Asian script seen in this
document. Smaller biases cover unspaced Han/Latin transitions, underscores
following Han, and newlines ending an Asian-language chat message.
"""
READS = ()


def script(char):
    if char == '�':
        return 'fragment'
    n = ord(char) if char else 0
    for low, high, name in (
        (0x4e00, 0x9fff, 'han'), (0x3040, 0x30ff, 'kana'),
        (0x0e00, 0x0e7f, 'thai'), (0xac00, 0xd7af, 'korean'),
        (0x0400, 0x04ff, 'cyrillic'),
    ):
        if low <= n <= high:
            return name
    return 'ascii' if n < 128 else 'other'


# Current space-prefixed writing system -> preceding token's final script.
# Coefficients summarize training activations; an 8% space-pulse gain below
# comes from a training-only causal-importance-weighted calibration.
PULSES = {
    'han': {'han': -1.85, 'kana': -0.67, 'ascii': 1.22,
            'other': 0.44, 'fragment': -0.24},
    'kana': {'han': -1.58, 'kana': -0.65, 'ascii': 0.84,
             'other': 0.26, 'fragment': -0.57},
    'thai': {'thai': -0.85, 'ascii': 0.48},
}
BARE_SPACE = {'han': -1.7, 'kana': -1.0, 'thai': -1.0,
              'korean': -0.57, 'cyrillic': -0.32,
              'other': -0.16, 'fragment': -0.25}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_doc = (len(prefix.token_ids) == 1 or
               prefix.document_ids[-1] != prefix.document_ids[-2])
    recent = 'other' if new_doc or carry is None else carry
    language = recent
    for char in token:
        seen = script(char)
        if seen in ('han', 'kana', 'thai', 'korean'):
            language = seen
    if new_doc:
        return language, 0.0

    left = prefix.token_strings[-2]
    previous = script(left[-1:])
    spaced_left = left.startswith(' ')
    current = script(token[:1])
    if not token.startswith(' '):
        value = 0.0
        if current == 'han':
            value = {'han': 0.015, 'kana': -0.01,
                     'fragment': -0.04}.get(previous, -0.075)
        elif token == '_' and previous == 'han':
            value = -0.41
        elif token == '\n' and left == '<|im_end|>':
            ending = ''
            if (len(prefix.token_ids) > 2 and
                    prefix.document_ids[-3] == prefix.document_ids[-1]):
                ending = prefix.token_strings[-3][-1:]
            n = ord(ending) if ending else 0
            asian_end = (script(ending) in ('han', 'kana') or
                         0x3000 <= n <= 0x303f or 0xff00 <= n <= 0xff65)
            value = -0.55 if asian_end else 0.04
        elif token.isspace() and previous == 'han':
            value = -0.15
        elif token[:1].isascii() and token[:1].isalpha():
            value = {'han': 0.18, 'kana': 0.14}.get(previous, 0.0)
        return language, value

    if token.isspace():
        value = BARE_SPACE.get(previous, 0.0)
        return language, 1.08 * value * (0.65 if spaced_left else 1.0)

    fragment = token[1:2] == '�'
    current = recent if fragment else script(token[1])
    value = PULSES.get(current, {}).get(previous, 0.0)
    if not fragment:
        if current == 'han':
            value *= 0.8 if value < 0 else 0.92
        elif current == 'kana':
            value *= 0.65
    if spaced_left and current in PULSES:
        if previous in ('han', 'kana', 'thai'):
            value *= 0.3
        elif previous in ('ascii', 'other') and current in ('han', 'kana'):
            value = max(value, 1.2 if current == 'han' else 0.96)
    return language, float(1.08 * value)

programs.haiku:
"""Space-led tokens that open a CJK character, signed by the script just before (candidate 4).

A token that begins with a space and carries the first byte of a CJK character (shown as
' �') or a whole CJK character is the start of a CJK word inside running text.
Whether it pushes the component up or down depends on the character just before it:
