programs.sol:
"""Approximate a software-testing and setup vocabulary response.

Testing tools, mocks/fixtures, configuration, and framework wiring are
negative, often more strongly in qualified code spellings. Function-call
syntax and common programming/output words add smaller corrections.
The previous token recognizes a few conventional compounds; a software
flag persists within each document. Unknown text mostly defaults to zero.
This groups related names rather than reproducing individual token quirks.
"""
import re

READS = ()

# Semantic families share a response, not individual token-ID weights.
CLASSES = [
    ('tools', -.80, 'pytest unittest junit jupiter testng jest jasmine mocha '
     'chai vitest supertest testify phpunit mockito hamcrest assertj cucumber '
     'eslint tslint pylint stylelint babel webpack gulp'),
    ('frameworks', -.65, 'springframework illuminate laravel svelte nestjs '
     'graphql express django flask fastapi lombok doctrine hibernate '
     'swagger vertx'),
    ('test support', -.50, 'mock mocked mocks stub stubs sinon fixture fixtures '
     'faker suite suites testcase tester matchers assertions'),
    ('wiring', -.40, 'schema schemas joi serde validate validator validators '
     'server servers router routers plugin plugins adapter adapters logger getlogger'),
    ('execution', -.43, 'execute runner runners'),
    ('commands', -.23, 'run build builder install require requires lint'),
    ('entry files', -.28, 'index readme'),
    ('setup machinery', -1.2, 'middleware middlewares dirname cwd'),
]
WORDS = {w: (kind, value) for kind, value, words in CLASSES for w in words.split()}
SOFTWARE = set('npm node python javascript typescript import export console '
               'compiler script scripts code testbed workspace'.split())
OUTPUT_WORDS = set('import export console log debug info result error file '
                   'token key util utils new null nil try void'.split())
SUFFIXES = set('py java php go rb rs cpp cs h sh xml yaml yml txt jar'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', False)
    _, previous, software = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    word = s.lstrip('._-/\\([<@$').lower()
    form = 'space' if token[:1].isspace() else 'bare'
    if s[:1] in ('.', '\\', '@'):
        form = 'member'
    elif s[:1] in ('/', '-'):
        form = 'path'
    elif s.startswith('_'):
        form = 'snake'
    software = (software or word in SOFTWARE or s in
                ('<tool_call>', '<tool_response>', '->', '=>', '.py', '.js',
                 '.ts', '.java', '.go', '/workspace', '/testbed'))
    initial = re.search(r'(?:^|[^A-Za-z])([A-Za-z])\Z', previous)
    if word not in WORDS and initial and token.isalpha() and len(token) >= 5:
        joined = initial.group(1).lower() + word
        if joined in WORDS:
            word = joined

    value = 0.
    if s.startswith('(') and len(s) > 1 and s[1].isalpha():
        value = -.06 if len(s) == 2 else -.29
    if s in ('((', '([', '([]', '(*'):
        value = -.27
    if s == '`' and token[:1].isspace():
        value = -.10
    value += {'/__': -.22, '__/': -.22, '__': .055, '::': .10}.get(s, 0.)
    if s.startswith('.') and word in SUFFIXES:
        value = .12
    if word in OUTPUT_WORDS and not s.startswith('('):
        value = .08
    if word in WORDS:
        kind, strength = WORDS[word]
        scale = {'space': .7, 'member': 1.3, 'path': 1.2, 'snake': .8}.get(form, 1.)
        if kind == 'entry files' and s.startswith('/'):
            scale = 2.6
        if kind == 'tools' and form in ('member', 'path'):
            scale = 1.7
        if kind in ('wiring', 'commands', 'frameworks', 'test support'):
            strength *= 1.3 if software else .7
        if word in ('jest', 'express') and form == 'space' and not software:
            scale = .05
        value += strength * scale
    if word in ('test', 'tests', 'testing'):
        strength = {'test': -.21, 'tests': -.50, 'testing': -.48}[word]
        value = {'member': -.75, 'path': -.14, 'snake': -.34}.get(form, strength)
        if form == 'space':
            value = {'test': -.35, 'tests': -.48, 'testing': -.32}[word]
            if not software:
                value *= .5
    if word == 'tests' and previous.strip() in ('__', '/__'):
        value = -.88
    if word == 'config':
        value = {'space': -.45, 'member': -.75, 'path': -.58,
                 'snake': -.29}.get(form, -.63)
    if word in ('spec', 'specs'):
        value = {'space': -.28, 'member': -1.05, 'path': -.42}.get(form, -.65)
    if word in ('ts', 'tsx', 'typescript'):
        value = -.36 if form != 'bare' else -.08
        if word == 'typescript':
            value = -.55
        if s == '.ts' and previous.strip() in ('.test', '.spec'):
            value = -.63
    if word in ('env', 'getenv'):
        value = -.9 if form == 'member' else -.2
    if word in ('environment', 'environments', 'configuration', 'settings', 'options'):
        value = -.2 if software else .04
    if word.startswith(('tobe', 'tohave', 'tomatch', 'toequal', 'tothrow')):
        value = -.85
    if word in ('beforeeach', 'aftereach', 'beforeall', 'afterall'):
        value = -1.5
    if word in ('expect', 'describe'):
        value = -.3 if software else -.04
    if word == 'config' and previous.strip().lower() == 'ts':
        value = -1.35
    if s == '.env' and previous.strip() == 'process':
        value = -1.65
    if word == 'types' and previous.rstrip().endswith('@'):
        value = -1.1
    if s == '.js':
        value = {'next': -.85, 'node': -.30, '.config': -.42,
                 '.test': -.12, '.spec': -.18}.get(previous.strip().lower(), .04)
    if s in ('<tool_call>', '<tool_response>', '</tool_response>'):
        value = {'<tool_call>': -.18, '<tool_response>': -.08,
                 '</tool_response>': .19}[s]
    return (doc, token, software), float(value)

"""Recognize tab indentation and a lexical contrast in qualified phrases.

The largest response is to standalone or repeated tab characters. Tabs joined
to letters, spaces or newlines are weaker. A second response distinguishes
technical quantities ('standard deviation', 'formal charge') from abstract
rules and frameworks ('basic principles', 'general rule'). These are surface
phrase rules, not a claim that the component understands those subjects.
A nonbreaking space following another, and the tool-call opener, have small
positive responses too. Unmatched tokens receive zero. Only the preceding
token is remembered, and that memory resets at document boundaries.
"""
READS = ()

QUALIFIERS = set('''standard standards general basic fundamental formal common
solid fixed specific clear definite default strict base universal normal
simple established instruction'''.split())
QUANTITIES = set('''deviation deviations error errors curve weight gravity charge
angle factor factors difference solution solutions power effect effects part
parts coefficient coefficients score value values force normal'''.split())
FRAMEWORKS = set('''rule rules principle principles definition definitions concept
concepts idea ideas understanding knowledge formula guideline guidelines set
sets template structure premise outline agreement consensus foundation limit
limitations requirement requirements convention conventions'''.split())


def tabs_response(text, previous, start):
    count = text.count('\t')
    if text.strip(' \t\r\n'):
        return 0.07 if previous.endswith('\t') else -0.03
    if text.endswith('\n'):
        return min(0.35, 0.06 * count) if count > 1 else 0.025
    if text.endswith(' '):
        return 0.05 if len(text) - count == 1 else -0.04
    if start:
        return 0.835 if count == 1 else 1.14
    if previous.endswith('\t'):
        value = 0.65
    elif count > 1:
        value = min(0.68, 0.56 + 0.045 * (count - 2))
        if not previous.endswith('\n'):
            value += 0.085 + 0.015 * min(count - 2, 3)
    else:
        value = 0.15 if previous.isdigit() else 0.265
    spaces = text.count(' ')
    if spaces == 1 and text.startswith(' '):
        value += 0.13
    elif spaces and count > 1:
        value -= min(0.2, 0.04 * spaces)
    return value


def phrase_response(word, modifier):
    if modifier == 'standard':
        if word in {'deviation', 'deviations'}:
            return 0.915
        if word in {'error', 'errors', 'dev', '_dev'}:
            return 0.70
        if word in {'curve', 'normal', 'model', 'library', 'scaler', 'buttons'}:
            return 0.45
    if modifier == 'general':
        if word.startswith('rel'):
            return 0.82
        if word in {'electric', 'motors', 'partner'}:
            return 0.60
        if word in {'election', 'hospital', 'manager', 'public', 'staff'}:
            return 0.32
    if modifier in QUALIFIERS:
        if word in FRAMEWORKS:
            if word in {'rule', 'rules', 'principle', 'principles'}:
                if modifier in {'general', 'basic', 'fundamental', 'strict',
                                'definite', 'base', 'standard'}:
                    return -0.55
                return -0.30
            return -0.32
        if word in QUANTITIES:
            if modifier in {'standard', 'general', 'formal', 'fundamental'}:
                return 0.50
            if modifier in {'specific', 'clear', 'default', 'definite',
                            'universal', 'simple'}:
                return 0.14
            return 0.28
    if word in {'rule', 'rules', 'principle', 'principles'}:
        return -0.10
    if modifier in {'rule', 'rules', 'standards'} and word == 'set':
        return -0.45
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    if '\t' in text:
        value = tabs_response(text, previous, start)
    elif text == '\xa0':
        value = 0.14 if previous.endswith('\xa0') else -0.04
    elif text == '<tool_call>':
        value = 0.172
    else:
        modifier = previous.strip(' ._').lower()
        if previous.lower().endswith('standard'):
            modifier = 'standard'
        value = phrase_response(text.strip().lstrip('._').lower(), modifier)
    return (doc, text), float(value)

