    "following", "think", "evaluate", "explain", "explains", "estimate", "track", "monitor",
    "identify", "detect", "discover", "measure", "measures", "study", "reflect", "enhance",
    "resolve", "indicates", "follow", "follows", "watch", "record", "records", "define",
    "satisfy", "control", "answer", "handle", "minimize", "conclude", "list", "lists",
    "cover", "covers", "reduce", "reduces", "improve", "achieve", "display", "regarding",
    "mention", "mentions", "examine", "inspect", "test", "explore", "observe", "verify",
    "validate",
}
LIGHT_VERBS = {
    "make", "makes", "made", "use", "using", "used", "put", "get", "got", "gets", "have",
    "has", "had", "having", "become", "became", "take", "takes", "give", "gives", "need",
    "keep", "do", "does", "be", "is", "was", "are", "were",
}
PLACE_PREPS = {
    "about", "into", "during", "over", "under", "across", "through", "along", "among",
    "below", "above", "out", "off", "down", "around", "against", "throughout", "inside",
    "outside", "towards", "behind", "between", "within", "up", "upon",
}
WEAK_PREPS = {"on", "to", "for", "at", "with", "like", "than", "after", "since"}
NEUTRAL = {"of", "in", "from", "by", "as", "if", "when", "which", "where", "whether"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    weight = DETERMINERS.get(tok)
    if weight is None or len(prefix) < 2:
        return carry, 0.0
