"""An unfinished opening parenthesis attached to an expression or identifier.

The response is strongest when '(' starts a token together with a word,
quote, or another bracket. A preceding identifier adds strength (long names
more than short mathematical variables); receiver and function-definition
words soften the response. State is just the last 100 characters of this
document, reset at document boundaries, to recognize the preceding identifier.
A whitespace-separated '(' and a finished empty pair mostly get no response.
This is a lexical approximation; it omits token-specific and broader-context
variation in the actual component.
"""
import re

READS = ()
RECEIVERS = {'self', 'this', 'super', 'cls'}
FUNCTION_WORDS = {'function', 'lambda', 'def'}
MATH_FUNCTIONS = set('sqrt sin cos tan log ln exp abs min max floor ceil'.split())


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        before = ''
