        before = carry[1]
    token = prefix.token_strings[-1]
    next_carry = (document, (before + token)[-100:])
    value = 0.0
    opening = token.lstrip()
    spaced = opening != token
    if opening.startswith('(') and opening.count('(') > opening.count(')'):
        tail = opening[1:]
        match = re.search(r'[\w.]+\Z', before)
        word = match[0] if match and not spaced else ''
        # Bare '(' and '(' fused to a word share an attachment signal.
        if not spaced and (not tail or tail.isspace() or tail.isalpha()):
            value = -0.06
            if word:
                value += 0.39 + 0.05 * min(len(word), 8)
                if word in MATH_FUNCTIONS:
                    value -= 0.12
                if word.isdigit():
                    value -= 0.17
                if not word.isascii():
                    value -= 0.27
            if '\n' in tail:
                value += 0.13
            if tail.isalpha():
                if len(tail) == 1:
                    value += 0.54
                else:
                    value += 0.84 + 0.043 * max(0, min(len(tail), 7) - 2)
                if len(tail) > 1 and tail[0].isupper():
                    value += 0.14
                if tail in RECEIVERS:
                    value -= 0.27
                if tail in FUNCTION_WORDS:
                    value -= 0.55
        elif tail:
            # Other expression starters: strings, brackets, escapes and operators.
            first = tail[0]
            if first in "\"'`“":
                value = 0.43 if spaced else (1.00 if word else 0.70)
            elif first in '([{':
                value = 0.82 if spaced else 1.30
                if first == '{' and not spaced:
                    value = 1.05
                if ')' in tail:
                    value -= 0.50
            elif first == '\\':
                if spaced:
                    value = 0.50 if '<' in tail or '>' in tail else 0.05
                elif '"' in tail:
                    value = 1.25
                else:
                    value = 0.09 + 0.22 * bool(word) + 0.058 * min(len(word), 8)
            elif first in '$@&_|':
                value = 0.30 if spaced else 1.12
            elif first == '!':
                value = 0.67 if spaced else 0.95
            elif first == '-':
                value = 0.04 if spaced else (
                    0.21 + 0.22 * bool(word) + 0.038 * min(len(word), 8)
                )
            else:
                value = 0.35 if spaced else 0.70
    elif token.startswith('!('):
        value = 0.22 + (0.60 if len(token) > 2 else 0.0)
    elif token == '()':
        value = 0.08
    return next_carry, float(value)

