            if not text[0].isspace():
                value -= 0.052
            if previous in MATH_FORM:
                value -= 0.079
            if previous in {'contact', 'consent'}:
                value = 0.50

    # 件 marks items/documents; the preceding stems identify letters or copies.
    if raw in {'件', '一件', '是一件'}:
        value += 0.273
        if tail.endswith(('信', '证', '證', '扫描', '掃描', '复印', '複印')):
            value = 0.65
    if raw in {'原件', '复印件'}:
        value = 0.75 if raw == '原件' else 0.45
    if raw in {'人', '人的'} and tail.endswith(LEGAL_PARTIES):
        value = 0.75
    # 签发 means to issue/sign; 事例 is a case/example.
    if raw == '发' and tail.endswith('签'):
        value = -0.9
    if raw == '例' and tail.endswith('事'):
        value = 0.6
    if raw == '事':
        value = 0.345 if first else 0.05
    if raw in CHINESE_TRANSFERS:
        value -= 0.146
        if raw in CHINESE_ISSUANCE:
            value -= 0.216
    if raw in CONTENT_TRANSLATIONS:
        value += 0.163
    if raw == 'предмет':
        value += 0.25
    if raw in {'✓', '✔'}:
        value += 0.109

    if first:
        value *= 2.0
    return (doc, (tail + text)[-120:]), float(value)

"""Inline backticks give positive pulses; liking/loving words give negative ones.

Backtick pulses weaken when a backtick occurred recently, and when closing
punctuation is attached. Tokens containing multiple backticks get no pulse.
Preference words respond most negatively after a subject or auxiliary.
The only state is the previous word and the distance from the last backtick;
it resets at document boundaries. Unrecognized tokens predict zero.
"""
READS = ()
SUBJECTS = {'i', 'you', 'we', 'they', 'he', 'she', 'who'}
AUXILIARIES = {'would', 'could', 'should', 'will', "'d", '’d', "'t", '’t'}
ADVERBS = {'really', 'always', 'also', 'never', 'just', 'still', 'absolutely'}
PREFERENCES = {'like', 'likes', 'liked', 'love', 'loves', 'loved'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 10000, '')
    _, gap, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if token.count('`') == 1:
        before, after = token.split('`')
        spaced = token.startswith(' ')
        strength = 1.19 + 0.15 * spaced
        attenuation = (0.76 - 0.12 * spaced) / gap ** 0.4
        value = strength - attenuation
        if any(c in after for c in ',.;:)]}'):
            value -= 0.46
        if '\n' in after:
            value -= 0.48
        elif after.startswith(('"', "'")):
            value -= 0.67
        elif after and not after[0].isalpha() and not any(
            c in after for c in ',.;:)]}'
        ):
            value -= 0.35
    elif token.startswith(' ') and word in PREFERENCES:
        personal = previous in SUBJECTS | AUXILIARIES
        if word == 'like':
            value = (-0.66 if personal else
                     -0.30 if previous in ADVERBS else -0.06)
        elif word == 'love':
            value = (-0.53 if personal else
                     -0.36 if previous in ADVERBS else -0.12)
        elif word in {'liked', 'loved'}:
            value = (-0.54 if personal else
                     -0.45 if previous in ADVERBS else -0.22)
        else:
            value = -0.41 if personal else -0.16
    gap = 1 if '`' in token else min(gap + 1, 10000)
    return (doc, gap, word), float(value)

