"""Lexical pulses for hearing, smelling, seeing, and encountering.

This detector is strongest on hearing words and on bare 闻/聞 (hear or smell).
Chinese/Japanese compounds have their own, usually smaller pulses. News and
rumour prefixes weaken 闻/聞. Certain following prepositions inherit a pulse.
A separate contribution-word family gives negative responses. Other tokens get
zero; the component's small, diffuse background fluctuations are not explained.
"""
READS = ()

# English sense-word spellings, matched to the whole decoded token.
SENSE_WORDS = {
    'hear': 0.80, 'heard': 0.98, 'hearing': 0.96, 'hears': 0.97,
    'listen': 0.33, 'listens': 0.33, 'listened': 0.33, 'listening': 0.41,
    'smell': 0.67, 'smelled': 0.65, 'smells': 0.34, 'smelling': 1.05,
    'scent': 0.42, 'sight': 0.40, 'see': 0.06, 'seen': 0.06, 'saw': 0.14,
    'seeing': 0.19, 'visible': 0.19, 'visibility': 0.33,
    'witness': 0.15, 'witnessed': 0.28, 'witnessing': 0.32,
    'noticeable': 0.69, 'noticeably': 0.22, 'touching': 0.16,
}

# 听/聽 and 聞: hearing; 见/見: seeing; 嗅: smelling;
# 遇/逢: encountering; 触/觸: touching; 吸: drawing in.
PERCEPTION_WORDS = {
    '听': 0.80, '聽': 1.05, '听说': 1.86, '听到': 1.71,
    '听见': 1.52, '聽到': 1.39, '听力': 1.19,
    '听说过': 0.84, '听了': 0.71, '听取': 0.71, '听得': 0.76,
    '听着': 0.73, '听过': 0.61, '聆听': 0.55, '倾听': 0.50,
    '闻言': 1.71, '闻名': 1.50, '嗅': 1.24,
    '聞き': 0.98, '聞く': 1.30, '聞いた': 0.78, '聞いて': 0.60,
    '见': 1.06, '見': 1.06, '睹': 1.26, '看到': 0.79,
    '看见': 0.62, '看到了': 0.58, '见到': 0.83,
    'を見': 0.81, '見る': 0.54, 'を見る': 0.56, 'を見て': 0.36,
    '見た': 0.17, '望': 0.45,
    '遇': 0.69, '遇到': 0.52, '相遇': 0.63, '出会い': 0.69,
    '逢': 0.58, '触': 0.51, '觸': 0.51, '吸': 0.50,
    '得知': 0.99, '获悉': 0.39, '新闻': 0.66, '新聞': 0.41,
}
RUMOUR_PREFIXES = {'丑', '醜', '秘', '绯', '緋', '趣', '无', '無'}


def lexical(token):
    word = token.strip()
    lower = word.lower()
    if lower in SENSE_WORDS:
        value = SENSE_WORDS[lower]
        # Capitalized hearing words and fragments differ from spaced lowercase.
        if lower in {'hear', 'heard', 'hearing'}:
            if word[0].isupper():
                value = 0.79 if lower == 'hearing' else 0.47
            elif not token.startswith(' '):
                value = 0.49 if lower == 'heard' else 0.18
        if lower == 'see':
            value = -0.04 if word[0].isupper() else (
                0.06 if token.startswith(' ') else 0.22
            )
        return value
    if word in PERCEPTION_WORDS:
        return PERCEPTION_WORDS[word]
    if lower == '.visible':
        return 0.45
    # Contribution, in prose or software package names, is a negative family.
    stem = lower.lstrip('._-')
    if stem in {'contributed', 'contributing'}:
        return -0.49
    if stem in {'contributor', 'contributors'} or word == 'Contrib':
        return -0.39
    if lower == '.contrib':
        return -0.72
    if stem in {'contribute', 'contributes', 'contrib'}:
        return -0.21
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = lexical(token)
    if word in {'闻', '聞'}:
        value = 5.0 if word == '闻' else 4.4
        if previous.endswith('新'):
            value = 2.4
        elif previous in RUMOUR_PREFIXES:
            value = 2.95
    elif lower == 'of' and previous in {'smell', 'heard', 'hear', 'scent', 'sight'}:
        value = 0.73 if previous in {'smell', 'heard'} else 0.43
    elif lower == 'to' and previous in {'listen', 'listening', 'listened'}:
        value = 0.29
    elif lower in {'the', 'that'} and previous in {'hear', 'heard', 'hearing', 'hears'}:
        value = 0.28
    elif lower in {'to', 'by'} and previous in {'contributed', 'contributing'}:
        value = -0.34 if lower == 'by' else -0.16
    elif word in {'到', '到了'} and previous == '嗅':
        value = 1.05
    return (document, lower), float(value)

programs.luna:
"""Approximate the rare sensory-language feature in this MLP component.

Its clearest positive responses are on words for hearing and smelling, plus
common Chinese and Japanese hearing/seeing words. The rule predicts these
distinctive lexical cases and ignores weak, less reliable matches.
"""

READS = ()

HEARING = {"hear", "hears", "heard", "hearing"}
LISTENING = {"listen", "listens", "listened", "listening"}
SMELLING = {"smell", "smells", "smelled", "smelling"}
SCENT = {"scent", "scents"}
SIGHT_NOUNS = {"sight", "sights"}
SEEING = {"seeing"}
EAR_CHARACTERS = set("闻聞听聽")
EYE_CHARACTERS = set("见見望睹")
SMELL_CHARACTERS = set("嗅")
TOUCH_CHARACTERS = set("触觸")
LOOK_CHARACTER = "看"
KNOW_WORDS = {"得知", "获悉", "獲悉", "知晓", "聽說", "听说"}
TURKISH_SEE = {"gör", "görd"}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = (None, "", False) if carry is None or carry[0] != doc else carry
    tail = previous[1]

    # Track a split English word, while also checking the token on its own.
    raw_tail = ""
    for char in text:
        if char.isalpha() and char.isascii():
            tail += char.lower()
            raw_tail += char.lower()
        else:
            tail = ""
            raw_tail = ""

    standalone = text.strip().lower().strip(".,!?;:'\"()[]{}-")
    current = raw_tail in HEARING or tail in HEARING
    if current:
        value = 0.95
    elif raw_tail in SMELLING or tail in SMELLING:
        current = True
        value = 0.65
    elif raw_tail in SCENT or tail in SCENT:
        current = True
        value = 0.45
    elif raw_tail in LISTENING or tail in LISTENING:
        current = True
        value = 0.4
    elif raw_tail in SIGHT_NOUNS or tail in SIGHT_NOUNS:
        current = True
        value = 0.4
    elif raw_tail in SEEING or tail in SEEING:
        current = True
        value = 0.15
    elif standalone in TURKISH_SEE:
        current, value = True, 0.55
    elif any(char in text for char in EAR_CHARACTERS):
        current, value = True, 0.9
    elif any(char in text for char in EYE_CHARACTERS):
        current, value = True, 0.45
    elif any(char in text for char in SMELL_CHARACTERS):
        current, value = True, 0.65
    elif any(char in text for char in TOUCH_CHARACTERS):
        current, value = True, 0.25
    elif standalone == "目":
        current, value = True, 0.35
    elif LOOK_CHARACTER in text:
        current, value = True, 0.3
    elif any(word in text for word in KNOW_WORDS) or "遇" in text:
        current, value = True, 0.7
    elif text.strip().lower() == "of" and previous[2]:
        value = 0.35
    else:
        value = 0.0
    return (doc, tail, current), value

programs.sol:
"""A selective detector of conversational pivots, responses, and negation.

Wait/Hmm/But are strongest. Other listed conversational words are stronger
when capitalized or following a pause or 'but'. Familiar phrases distinguish
'of course', 'you know', and 'I mean' from ordinary word uses. Selected
foreign-language discourse cues and their compound prefixes are included.
Only the immediately previous token is kept, reset between documents.
Tokens matching none of these rules are zero; smaller lexical effects
are omitted.
"""
READS = ()

# Lowercase versus initial-capital token; not a universal synonym detector.
CUES = {
    'wait': (.65, 1.2), 'hmm': (1.1, 1.1), 'but': (.45, .95),
    'so': (.10, .49), 'then': (.35, .49), 'now': (.20, .60),
    'well': (.15, .82), 'let': (.20, .40), 'why': (.55, .80),
    'see': (.30, .60), 'look': (.25, .65), 'remember': (.25, .75),
    'even': (.15, .45), 'still': (.20, .65), 'yet': (0., .65),
    'actually': (.20, .53), 'given': (.15, .30),
    'what': (0., .20), 'how': (-.05, .15), 'just': (-.05, .27),
    'especially': (.20, .60), 'again': (.12, .45),
    'yes': (.75, .90), 'yeah': (1.1, 1.1), 'no': (.35, .60),
    'ok': (.50, .60), 'okay': (.45, .78), 'oh': (.25, .72),
    'ah': (.25, .70), 'wow': (.20, .60), 'thank': (.40, .72),
    'welcome': (.34, .45), 'sure': (0., .85), 'indeed': (.18, .45),
    'certainly': (.39, .60), 'right': (.20, .40), 'correct': (.25, .45),
}
CLAUSE_CUES = set('''but so then now well let why see look remember even
still yet actually given what how just especially again'''.split())
QUIET = set('''however although though despite instead rather thus since
perhaps more most only first next always already might too here'''.split())
# Contrast, negation, demonstratives, and conversational particles.
FOREIGN = {
    'mais': .53, 'mas': .40, 'pero': .70, 'aber': .48, 'doch': .63,
    'dann': .52, 'wenn': .60, 'nicht': .29, 'auch': .32,
    'но': .83, 'что': .49, 'как': .54, 'а': .37, 'если': .50,
    '这': .63, '這': .60, '那': .36, '但': .51, '但是': .47,
    '其实': .45, '当然': 1.13, '不能': .53, '不': .23,
    '可': .43, '真': .43, '看': .41, '而且': .62,
    'しかし': 1.15, 'それ': 1.34, 'そんな': 1.31,
    'もちろん': 1.52, 'どう': 1.16, 'そう': .80, 'という': .67,
    'そして': 1.08, 'この': .44, 'その': .36, 'まあ': 1.70,
}
PHRASES = {
    ('of', 'course'): .93, ('after', 'all'): .75,
    ('i', 'know'): .85, ('you', 'know'): .75, ('we', 'know'): .40,
    ('i', 'mean'): 1., ('you', 'mean'): .65, ('not', 'yet'): -.53,
    ('and', 'yet'): .88, ('as', 'well'): .02, ('but', 'that'): .33,
}
# Weaker responses when a discourse cue starts a larger Chinese/Japanese token.
COMPOUND_CUES = {
    '这': .34, '那': .22, '但': .46, '不': .21,
    '可': .18, '真': .21, '看': .19,
    'それ': .69, 'そう': .74, 'という': .51,
}
NOT_AFTER = {
    'do': -.13, 'does': -.20, 'did': -.27, 'is': .21, 'are': .21,
    'was': 0., 'were': 0., 'has': 0., 'have': 0., 'had': 0.,
    'if': 0., 'would': 0., 'could': .29, 'am': .4,
    "'m": .5, '’m': .5, "'s": .4, '’s': .4, 'and': .4,
}
SPECIAL = {
    '<think>': .58, '</think>': .93, '<tool_call>': .31,
    '</tool_call>': -.39, '<tool_response>': .16,
}


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    token, before = raw.strip(), prev.strip().lower()
    word, last = token.lower(), prev.rstrip()[-1:]
    capital = token[:1].isupper() and not (len(token) > 1 and token.isupper())
    pause = last in {',', ';', ':', '!', '?', '—', '–', '-', '(', '.'}
    value = SPECIAL.get(token, 0.)
    if word in CUES:
        value = CUES[word][int(capital)]
        if word in CLAUSE_CUES and not capital:
            if before == 'but':
                value += .65
            elif before == 'and':
                value += .25
            elif pause:
                value += .32
        if not capital and not raw[:1].isspace() and prev[-1:].isalnum():
            value -= .20
    elif word in QUIET:
        value = -.13
    elif word in FOREIGN:
        value = FOREIGN[word]
        if word.isascii() or all('А' <= c <= 'я' for c in word):
            if not raw[:1].isspace() and prev[-1:].isalpha():
                value = 0.
    elif word == 'not':
        value = NOT_AFTER.get(before, .15)
        if (pause or before == 'but'
                or (capital and before not in {'do', 'does', 'did'})):
            value = .60
    elif word in {"'t", '’t'}:
        value = {'can': .94, 'couldn': .33, 'doesn': -.17,
                 'didn': -.22, 'wasn': -.10, 'won': .10}.get(before, 0.)
        if prev.strip()[:1].isupper() and before != 'can':
            value = .4
    elif word in {'cannot', 'never', 'course', 'know', 'mean'}:
        value = .65 if word == 'cannot' else .20
        if word == 'never' and capital:
            value = .55
        if word == 'know' and before in {'not', "'t", '’t', 'to'}:
            value = -.20
    elif word in {'and', 'that'}:
        value = .4 if capital else 0.
    elif token == 'I':
        value = .08
        if before in {'if', 'when', 'what', 'do', 'that'}:
            value = -.12
        elif before == 'but':
            value = .47
        elif pause or before == 'and':
            value = .22
    else:
        # Longest matching prefix; the cues here are one to three characters.
        value = COMPOUND_CUES.get(token[:3], COMPOUND_CUES.get(
            token[:2], COMPOUND_CUES.get(token[:1], value)))
    if word in {'what', 'how', 'why'} and before == 'so':
        value += .75
    if word == 'wait' and before == 'but':
        value = 1.75
    if word == 'no':
        if pause or before in {'but', 'wait', 'hmm'}:
            value = .8
        elif before in {'is', 'are', 'was', 'were', 'be', 'with'}:
            value = .04
    if word == 'well' and pause:
        value = 1.05
    if word == 'wait' and before in {'to', "'t", '’t'}:
        value = .18
    if word == 'right' and before in {'the', 'to', 'on'}:
        value = .02
    if len(token) > 1 and token.isupper() and word in {'and', 'not', 'no'}:
        value = .05
    return (doc, raw), float(PHRASES.get((before, word), value))

