    "beverage", "coffee", "tea", "alcohol", "sugar", "salt", "maize",
    "grain", "wheat", "cereal", "bread", "meat", "fish", "seafood",
    "chicken", "beef", "pork", "egg", "cheese", "fruit", "vegetable",
